"""Generate CertiGPU app icons (one-time setup, stdlib only).

The icon binaries can't live in git cleanly for every clone, so this script
regenerates them from embedded PNG data. Run once after cloning:

    python src-tauri/icons/generate_icons.py

Outputs (next to this script):
    icon.ico            Windows .exe icon (256px PNG-compressed entry)
    32x32.png           } referenced by tauri.conf.json
    128x128.png         } bundle.icon for installers
    128x128@2x.png      }
"""
import base64
import os
import struct

HERE = os.path.dirname(os.path.abspath(__file__))

PNG_256 = ""
PNG_128 = ""
PNG_32 = ""


def write(name, b64data):
    path = os.path.join(HERE, name)
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64data))
    print("wrote", path)


def write_ico(name, png_bytes):
    # ICO with a single PNG-compressed 256x256 entry (Vista+ compatible).
    header = struct.pack("<HHH", 0, 1, 1)
    entry = struct.pack(
        "<BBBBHHII",
        0, 0, 0, 0,          # 256x256, no palette
        1, 32,               # planes, bit depth
        len(png_bytes),      # data size
        6 + 16,              # data offset
    )
    path = os.path.join(HERE, name)
    with open(path, "wb") as f:
        f.write(header + entry + png_bytes)
    print("wrote", path)


def main():
    write("32x32.png", PNG_32)
    write("128x128.png", PNG_128)
    write("128x128@2x.png", PNG_256)
    write_ico("icon.ico", base64.b64decode(PNG_256))


if __name__ == "__main__":
    main()
